head.b:skin:
/* ==================== Design tokens ==================== */
:root{
  --color-bg:#ffffff;
  --color-surface:#f8fafc;
  --color-border:#e5e9f0;
  --color-text:#1e2532;
  --color-text-muted:#5b6472;
  --color-primary:#2563eb;
  --color-primary-dark:#1d4ed8;
  --color-accent:#0ea5a4;
  --radius-sm:8px;
  --radius-md:14px;
  --radius-lg:20px;
  --shadow-sm:0 1px 3px rgba(20,29,48,.06);
  --shadow-md:0 8px 24px rgba(20,29,48,.08);
  --container:1140px;
  --space-1:8px;
  --space-2:16px;
  --space-3:24px;
  --space-4:40px;
  --space-5:64px;
  --font-body:'Inter',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;
  --font-head:'Poppins',var(--font-body);
}

/* ==================== Reset ==================== */
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--color-bg);color:var(--color-text);font-family:var(--font-body);font-size:17px;line-height:1.75;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block;border-radius:var(--radius-sm)}
a{color:var(--color-primary);text-decoration:none}
a:hover{color:var(--color-primary-dark);text-decoration:underline}
h1,h2,h3,h4,h5,h6{font-family:var(--font-head);color:var(--color-text);line-height:1.3;font-weight:700;margin:1.4em 0 .6em}
ul,ol{padding-inline-start:1.3em}
.container{max-width:var(--container);margin:0 auto;padding:0 var(--space-2)}
button,input,textarea{font-family:inherit}

/* ==================== Top utility bar ==================== */
.top-bar{background:var(--color-text);color:#fff;font-size:13px}
.top-bar .container{display:flex;align-items:center;justify-content:space-between;gap:var(--space-2);padding-top:6px;padding-bottom:6px}
.top-bar .tagline{opacity:.85}
.social-icons{display:flex;gap:10px;align-items:center}
.social-icons a{display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;border-radius:50%;background:rgba(255,255,255,.12);color:#fff;transition:background .2s,transform .2s}
.social-icons a:hover{background:var(--color-primary);transform:translateY(-2px);text-decoration:none}
.social-icons svg{width:16px;height:16px;fill:currentColor}
.footer .social-icons a{background:rgba(255,255,255,.08)}

/* ==================== Header ==================== */
.header{background:#fff;border-bottom:1px solid var(--color-border);position:sticky;top:0;z-index:50;box-shadow:var(--shadow-sm)}
.header-inner{display:flex;align-items:center;justify-content:space-between;gap:var(--space-3);padding:14px 0}
.site-title{font-family:var(--font-head);font-size:26px;font-weight:800;letter-spacing:-.02em;margin:0}
.site-title a{color:var(--color-text)}
.site-title a:hover{text-decoration:none;color:var(--color-primary)}
.site-description{margin:2px 0 0;font-size:13px;color:var(--color-text-muted)}

.nav-toggle{display:none}
.nav-toggle-label{display:none;cursor:pointer;padding:8px;border-radius:var(--radius-sm)}
.nav-toggle-label span,.nav-toggle-label span::before,.nav-toggle-label span::after{display:block;width:24px;height:2px;background:var(--color-text);position:relative;transition:.2s}
.nav-toggle-label span::before{content:'';position:absolute;top:-7px}
.nav-toggle-label span::after{content:'';position:absolute;top:7px}

.main-nav ul{list-style:none;display:flex;gap:6px;margin:0;padding:0;flex-wrap:wrap}
.main-nav a{display:block;padding:10px 14px;border-radius:var(--radius-sm);color:var(--color-text);font-weight:600;font-size:15px}
.main-nav a:hover{background:var(--color-surface);color:var(--color-primary);text-decoration:none}

.search-form{display:flex;align-items:center;background:var(--color-surface);border:1px solid var(--color-border);border-radius:999px;padding:4px 4px 4px 14px}
.search-form input[type="text"]{border:0;background:transparent;outline:none;font-size:14px;width:150px}
.search-form button{border:0;background:var(--color-primary);color:#fff;width:32px;height:32px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center}
.search-form svg{width:15px;height:15px;fill:#fff}

@media (max-width:860px){
  .header-inner{flex-wrap:wrap}
  .nav-toggle-label{display:flex;flex-direction:column;gap:0;align-items:flex-end}
  .main-nav{width:100%;max-height:0;overflow:hidden;transition:max-height .25s ease}
  .nav-toggle:checked ~ .main-nav{max-height:400px}
  .main-nav ul{flex-direction:column;gap:0;padding:10px 0}
  .search-form{width:100%;margin-top:8px}
  .search-form input[type="text"]{flex:1;width:auto}
}

/* ==================== Breadcrumbs ==================== */
.breadcrumbs{font-size:13px;color:var(--color-text-muted);padding:14px 0 0}
.breadcrumbs a{color:var(--color-text-muted)}
.breadcrumbs span[aria-current]{color:var(--color-text);font-weight:600}

/* ==================== Ad slots (clean, non-intrusive, no popups) ==================== */
.ad-slot{margin:var(--space-3) 0;text-align:center}
.ad-slot .ad-label{display:block;font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:var(--color-text-muted);margin-bottom:6px}
.ad-slot .ad-box{min-height:90px;background:var(--color-surface);border:1px dashed var(--color-border);border-radius:var(--radius-md);display:flex;align-items:center;justify-content:center;color:var(--color-text-muted);font-size:13px}

/* ==================== Layout ==================== */
.page-body{padding:var(--space-4) 0}
.layout-grid{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:var(--space-4)}
@media (max-width:960px){.layout-grid{grid-template-columns:1fr}}

/* ==================== Posts (index list) ==================== */
.post-outer{background:#fff;border:1px solid var(--color-border);border-radius:var(--radius-lg);padding:var(--space-3);margin-bottom:var(--space-3);box-shadow:var(--shadow-sm);transition:box-shadow .2s,transform .2s}
.post-outer:hover{box-shadow:var(--shadow-md);transform:translateY(-2px)}
.post-title{font-size:26px;margin-top:0}
.post-title a{color:var(--color-text)}
.post-title a:hover{color:var(--color-primary);text-decoration:none}
.post-header .post-timestamp,.post-header .post-author{font-size:13px;color:var(--color-text-muted)}
.post-thumb{margin:0 0 var(--space-2);border-radius:var(--radius-md);overflow:hidden}
.post-snippet{color:var(--color-text-muted)}
.post-more{display:inline-block;margin-top:8px;font-weight:600}

/* ==================== Post body typography ==================== */
.post-body{font-size:17px}
.post-body h2{font-size:24px;margin-top:2em;padding-bottom:.4em;border-bottom:3px solid var(--color-primary);background:linear-gradient(90deg,var(--color-primary),transparent 55%) bottom left / 60% 3px no-repeat, none;position:relative}
.post-body h2{border-bottom:3px solid var(--color-border)}
.post-body h2::after{content:'';display:block;width:64px;height:3px;background:var(--color-primary);margin-top:-3px}
.post-body h3{font-size:20px;color:var(--color-primary-dark)}
.post-body p{margin:0 0 1.2em}
.post-body a{text-decoration:underline;text-underline-offset:3px}
.post-body blockquote{margin:1.4em 0;padding:.8em 1.2em;border-inline-start:4px solid var(--color-primary);background:var(--color-surface);border-radius:var(--radius-sm);color:var(--color-text-muted)}
.post-body img,.post-body iframe{margin:1em auto;border-radius:var(--radius-md)}
.post-body table{width:100%;border-collapse:collapse;display:block;overflow-x:auto}
.post-body table th,.post-body table td{border:1px solid var(--color-border);padding:8px 12px}
.post-body code{background:var(--color-surface);padding:2px 6px;border-radius:4px;font-size:.9em}
.post-body pre{background:#0f172a;color:#e2e8f0;padding:16px;border-radius:var(--radius-md);overflow-x:auto}

/* FAQ / CTA helper classes for use inside post content (see post template) */
.faq-item{border:1px solid var(--color-border);border-radius:var(--radius-md);padding:14px 18px;margin-bottom:12px;background:#fff}
.faq-item > strong{display:block;color:var(--color-primary-dark);margin-bottom:6px}
.cta-box{background:linear-gradient(135deg,var(--color-primary),var(--color-primary-dark));color:#fff;border-radius:var(--radius-lg);padding:var(--space-3) var(--space-3);margin:var(--space-4) 0;text-align:center}
.cta-box h3{color:#fff;margin-top:0}
.cta-box p{color:rgba(255,255,255,.9)}
.cta-box .cta-button{display:inline-block;margin-top:8px;background:#fff;color:var(--color-primary-dark)!important;font-weight:700;padding:12px 28px;border-radius:999px;text-decoration:none!important}
.cta-box .cta-button:hover{transform:translateY(-2px)}

/* ==================== Post footer / labels ==================== */
.post-footer{display:flex;flex-wrap:wrap;gap:10px;align-items:center;justify-content:space-between;margin-top:var(--space-3);padding-top:var(--space-2);border-top:1px solid var(--color-border);font-size:13px;color:var(--color-text-muted)}
.post-labels{display:flex;flex-wrap:wrap;gap:6px;list-style:none;padding:0;margin:0}
.post-labels a{background:var(--color-surface);border:1px solid var(--color-border);padding:4px 10px;border-radius:999px;font-size:12px;color:var(--color-text)}
.post-labels a:hover{background:var(--color-primary);color:#fff;text-decoration:none}

/* ==================== Pagination ==================== */
.blog-pager{display:flex;justify-content:space-between;margin:var(--space-4) 0}
.blog-pager a{background:var(--color-surface);border:1px solid var(--color-border);padding:10px 18px;border-radius:999px;font-weight:600}
.blog-pager a:hover{background:var(--color-primary);color:#fff;text-decoration:none}

/* ==================== Comments ==================== */
.comments{margin-top:var(--space-4);padding-top:var(--space-3);border-top:1px solid var(--color-border)}
.comments .comments-content{margin-top:var(--space-2)}

/* ==================== Sidebar widgets ==================== */
.sidebar .widget{background:#fff;border:1px solid var(--color-border);border-radius:var(--radius-lg);padding:var(--space-3);margin-bottom:var(--space-3);box-shadow:var(--shadow-sm)}
.sidebar .widget h2,.sidebar .widget h3{font-size:16px;text-transform:uppercase;letter-spacing:.04em;margin-top:0;padding-bottom:10px;border-bottom:2px solid var(--color-primary)}
.sidebar .PopularPosts ul{list-style:none;margin:0;padding:0}
.sidebar .PopularPosts li{padding:10px 0;border-bottom:1px solid var(--color-border)}
.sidebar .PopularPosts li:last-child{border-bottom:0}
.sidebar .PopularPosts .item-thumbnail{float:inline-start;width:60px;margin-inline-end:10px;border-radius:var(--radius-sm)}
.sidebar .newsletter p{color:var(--color-text-muted);font-size:14px}
.sidebar .newsletter .cta-button{display:block;text-align:center;background:var(--color-primary);color:#fff;font-weight:700;padding:12px;border-radius:var(--radius-sm)}
.sidebar .newsletter .cta-button:hover{background:var(--color-primary-dark);text-decoration:none}

/* ==================== Footer ==================== */
.footer{background:#111827;color:#cbd5e1;margin-top:var(--space-5)}
.footer .container{padding:var(--space-5) var(--space-2) var(--space-3)}
.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:var(--space-3)}
@media (max-width:760px){.footer-grid{grid-template-columns:1fr 1fr}}
@media (max-width:480px){.footer-grid{grid-template-columns:1fr}}
.footer h4{color:#fff;font-size:14px;text-transform:uppercase;letter-spacing:.06em;margin-top:0}
.footer a{color:#cbd5e1}
.footer a:hover{color:#fff}
.footer ul{list-style:none;padding:0;margin:0}
.footer li{margin-bottom:8px;font-size:14px}
.footer-bottom{border-top:1px solid rgba(255,255,255,.1);margin-top:var(--space-3);padding-top:var(--space-2);display:flex;flex-wrap:wrap;gap:10px;justify-content:space-between;font-size:13px;color:#94a3b8}
.attribution{font-size:12px;color:#64748b;text-align:center;padding:10px 0 0}

/* ==================== Misc ==================== */
.visually-hidden{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.back-to-top{position:fixed;inset-inline-end:20px;bottom:20px;width:44px;height:44px;border-radius:50%;background:var(--color-primary);color:#fff;display:flex;align-items:center;justify-content:center;box-shadow:var(--shadow-md);opacity:0;pointer-events:none;transition:opacity .2s,transform .2s;z-index:60}
.back-to-top.show{opacity:1;pointer-events:auto}
.back-to-top:hover{background:var(--color-primary-dark);text-decoration:none}
